--region init
function ActivityMidFestivalStoryItemBase:InitData(id)
    self.homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    self.entranceConf = self.homeDojo.entranceConf[id]
    local id = self.entranceConf.id
    self.questDojo = self.homeDojo.mainQuestHash[tostring(id)]
    ---@type MidFestivalMainQuestLocationVo
    self.mapPlaceVo = CfUtils.GetCfVo(AutoIds.IdSetting6085, "MidFestivalMainQuestLocationVo", checkNumber(id))
    self.isReachUnLockData = self.homeDojo:IsReachUnlockDate(id)
    self.tipInfo = self.homeDojo:TimeCountDownTips(id)

    self.config.isLock = (self.questDojo.status == Constants.MidFestivalMapStatus.LOCK) or
            (self.questDojo.status == Constants.MidFestivalMapStatus.NOW and (not self.isReachUnLockData))
    self.config.isGet = self.questDojo.status == Constants.MidFestivalMapStatus.PASS
    self:RefreshUI()
end
--endregion init

