--region private
function ActivityMidFestivalStoryItemBase:RefreshUI()
    local lockPicPath = checkString(self.mapPlaceVo.picture1)
    if not string.isEmpty(lockPicPath) then
        CfUtils.FillImage(self.ImgIconLock, lockPicPath)
    end
    local unLockPicPath = checkString(self.mapPlaceVo.picture2)
    if not string.isEmpty(unLockPicPath) then
        CfUtils.FillImage(self.ImgIconUnlock, unLockPicPath)
    end
    if not string.isEmpty(self.mapPlaceVo.name) then
        CfUtils.FillText(self.TextTitle, self.mapPlaceVo.name)
    end

    CfUtils.FillText(self.TextTime, self.tipInfo)
    CfUtils.SetActive(self.ImgLock, not self.isReachUnLockData)
    CfUtils.SetActive(self.ImgLine, not self.isReachUnLockData)

    CfUtils.SetActive(self.ImgIconLock, self.config.isLock)
    CfUtils.SetActive(self.ImgIconUnlock, not self.config.isLock and self.isReachUnLockData)
    --CfUtils.SetActive(self.ImgLock, self.config.isLock)
    CfUtils.SetActive(self.TextTitle, not self.config.isLock and self.isReachUnLockData)
    CfUtils.SetActive(self.ImgTitleBg, not self.config.isLock and self.isReachUnLockData)
    CfUtils.SetActive(self.ImgGet, self.config.isGet and self.isReachUnLockData)

    -- 玩家头像
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
   
    
    if self.PlayerHead then
        local gender = comp.playerDojo.gender
        ---@type ActivityMidFestivalPlayerHeadNode
        local scr = CfUtils.GetLuaScr(self.PlayerHead, "Game.Activity.MidFestival.StoryDialog.ButtonItem.ActivityMidFestivalPlayerHeadNode")
        scr:SetGender(gender)
        CfUtils.SetActive(self.PlayerHead, (self.questDojo.status == self.Constants.MapQuestStatus.NOW))
    end
    
    -- 通往箭头
    CfUtils.SetUISwitchImage(self.ImgArrow, self.config.isLock and 2 or 1)

    -- NEW符号
    local hasRedPoint = false
    local map = self.questDojo
    if map.status == Constants.MidFestivalMapStatus.NOW then
        local subList = ActivityMidFestivalMgr:LoadMainQuestLevelVoByPlaceId(checkString(map.questId))
        local questOfNew = self.homeDojo:GetNewItemInSubList(subList)
        if isNotNull(questOfNew) then
            hasRedPoint = true
        end
    end
    CfUtils.SetActive(self.ImgNew, hasRedPoint)
end
--endregion private

--region get / set
--endregion get / set

return ActivityMidFestivalStoryItemBase
